function effectFace(x){let c=card(x.id);return c?.faces?c.faces[x.face||0]:c}
function effectAsk(title,choices){return new Promise(resolve=>dialogPick(title,choices.map(o=>({label:o.label,fn:()=>resolve(o.value)}))))}
function effectMany(title,items,max){if(!items.length)return Promise.resolve([]);return new Promise(resolve=>{let picked=new Set;const paint=()=>{$('dialogContent').innerHTML=`<h3>${title}</h3><p class="sub">選択 ${picked.size} / 最大 ${max}</p><div class="pickgrid">${items.map((x,i)=>`<button data-effect-pick="${i}" class="${picked.has(i)?'primary':''}">${x.label}</button>`).join('')}</div><div class="actionrow"><button class="primary" id="effectConfirm">決定</button><button id="effectSkip">選ばない</button></div>`;$('overlay').style.display='flex';document.querySelectorAll('[data-effect-pick]').forEach(b=>b.onclick=()=>{let i=+b.dataset.effectPick;if(picked.has(i))picked.delete(i);else if(picked.size<max)picked.add(i);paint()});$('effectConfirm').onclick=()=>{$('overlay').style.display='none';resolve([...picked].map(i=>items[i].value))};$('effectSkip').onclick=()=>{$('overlay').style.display='none';resolve([])}};paint()})}
function effectTopMana(owner,n){let p=state.players[owner];for(let i=0;i<n&&p.deck.length;i++)p.mana.push(p.deck.pop())}
function effectDraw(owner,n){let p=state.players[owner];for(let i=0;i<n;i++){let x=p.deck.pop();if(!x){state.winner=1-owner;log(`${p.name}は山札切れで敗北。`);break}p.hand.push(x)}}
function effectOptions(owner,zone,filter=()=>true){return state.players[owner][zone].filter(filter).map(x=>({label:effectFace(x).name,value:x}))}
async function effectBounce(max,filter=()=>true,title='手札に戻すカードを選ぶ'){let a=state.players.flatMap((p,owner)=>p.field.filter(filter).map(x=>({label:`${p.name}：${effectFace(x).name}`,value:{owner,x}})));let picks=await effectMany(title,a,max);for(let z of picks){let p=state.players[z.owner];p.field=p.field.filter(x=>x.uid!==z.x.uid);p.hand.push(z.x)}return picks.length}
async function effectEntry(owner,x){let p=state.players[owner],id=x.id,f=x.face||0;
 if(id==='c2'&&f===0)effectTopMana(owner,3);
 if(id==='c4'){effectDraw(owner,3);let m=await effectMany('手札からマナに置くカードを選ぶ',effectOptions(owner,'hand'),1);m.forEach(z=>{p.hand=p.hand.filter(a=>a.uid!==z.uid);effectAddMana(owner,z)});let sh=await effectMany('手札に加えるシールドを選ぶ',effectOptions(owner,'shields'),1);sh.forEach(z=>{p.shields=p.shields.filter(a=>a.uid!==z.uid);p.hand.push(z)});let put=await effectMany('裏向きでシールド化する手札を選ぶ',effectOptions(owner,'hand'),1);put.forEach(z=>{p.hand=p.hand.filter(a=>a.uid!==z.uid);p.shields.push(z)})}
 if(id==='c6'){effectTopMana(owner,2);let m=await effectMany('手札に戻すマナを最大2枚選ぶ',effectOptions(owner,'mana'),2);m.forEach(z=>{p.mana=p.mana.filter(a=>a.uid!==z.uid);p.hand.push(z)})}
 if(id==='c8'){let a=state.players.flatMap((q,i)=>q.field.filter(z=>effectFace(z).kind==='creature').map(z=>({label:`${q.name}：${effectFace(z).name}`,value:{owner:i,x:z}})));let t=await effectAsk('破壊するクリーチャー',[...a.map(z=>({label:z.label,value:z.value})),{label:'選ばない',value:null}]);if(t)effectLeaveField(t.owner,t.x,'grave');for(let i=0;i<4&&p.deck.length;i++)p.grave.push(p.deck.pop())}
 if(id==='c9'){let a=state.players[1-owner].field.filter(z=>effectFace(z).kind==='creature');let picks=await effectMany('このターン、攻撃もブロックもできなくする相手クリーチャー（最大2体）',a.map(z=>({label:effectFace(z).name,value:z})),2);picks.forEach(z=>z.stunnedAt=state.turnNo)}
 if(id==='c15'&&f===1&&p.deck.length)p.shields.push(p.deck.pop());
 if(id==='c17'&&f===1)state.players[1-owner].field.filter(z=>effectFace(z).kind==='creature').forEach(z=>z.noAttackUntil=state.turnNo);
 if(id==='c19'&&f===0)effectTopMana(owner,1);
 if(id==='c21'&&f===1)effectTopMana(owner,1);
 if(id==='c23'&&f===1){let a=state.players.flatMap((q,i)=>q.field.filter(z=>effectFace(z).kind==='creature').map(z=>({label:`${q.name}：${effectFace(z).name}（${z.tapped?'タップ':'アンタップ'}）`,value:z})));let picks=await effectMany('タップまたはアンタップするクリーチャー（最大2体）',a,2);picks.forEach(z=>z.tapped=!z.tapped)}
 if(id==='c25'&&f===1){let picks=await effectMany('このターン、ブロッカーを与える自分のエレメント',effectOptions(owner,'field',z=>z.uid!==x.uid),1);picks.forEach(z=>z.tempBlockerUntil=state.turnNo)}
 await effectAttachTriggers(owner,x);
 if(effectFace(x).kind==='creature'&&p.field.some(z=>z.id==='c5'&&z.uid!==x.uid)){let go=await effectAsk('リーファ：山札の上をマナに置きますか？',[{label:'置く',value:true},{label:'置かない',value:false}]);if(go&&p.deck.length){effectTopMana(owner,1);let m=await effectMany('手札に戻すマナ（任意）',effectOptions(owner,'mana'),1);m.forEach(z=>{p.mana=p.mana.filter(a=>a.uid!==z.uid);p.hand.push(z)})}}
 render()}
async function effectAttachTriggers(owner,x){let c=effectFace(x);if(c.kind!=='creature')return;let n=c.name,checks={'c11':n.includes('アスナ'),'c13':n.includes('シノン'),'c15':n.includes('キリト'),'c17':!card(x.id)?.deckZone,'c19':n.includes('エギル'),'c21':n.includes('リーファ'),'c23':n.includes('アリス'),'c25':n.includes('ユージオ')};for(let id of Object.keys(checks)){if(!checks[id])continue;let p=state.players[owner],w=p.extra.find(z=>z.id===id),ph=card(id);if(!w)continue;let choices=ph.faces.map((z,i)=>({label:`${z.name}を装備する`,value:i})).filter(z=>ph.faces[z.value].kind==='weapon');if(!choices.length)continue;choices.push({label:'使わない',value:-1});let f=await effectAsk(`${c.name}の登場：超次元から装備しますか？`,choices);if(f<0)continue;p.extra=p.extra.filter(z=>z.uid!==w.uid);w.face=f;w.attachedTo=x.uid;p.field.push(w);log(`${ph.faces[f].name}を${c.name}に装備。`);if(id==='c15'&&f===1&&p.deck.length)p.shields.push(p.deck.pop());if(id==='c19'&&f===0)effectTopMana(owner,1)}}
async function effectSpell(owner,x){let p=state.players[owner],id=x.id,f=x.face||0;if(id==='c2'&&f===1){await effectBounce(3,z=>effectFace(z).kind==='creature','手札に戻すクリーチャー（最大3体）');log('幻影の一弾を解決。')}
 if(id==='c27'){for(let n=0;n<2;n++){let k=await effectAsk(`効果を選ぶ（${n+1}/2）`,[{label:'コスト6以下のエレメントを手札に戻す',value:0},{label:'山札の上3枚をマナに置き、マナ1枚を手札に戻す',value:1},{label:'SAOクリーチャーにスピードアタッカーを付与',value:2}]);if(k===0)await effectBounce(1,z=>effectFace(z).cost<=6,'手札に戻すエレメント');if(k===1){effectTopMana(owner,3);let m=await effectMany('手札に戻すマナ',effectOptions(owner,'mana'),1);m.forEach(z=>{p.mana=p.mana.filter(a=>a.uid!==z.uid);p.hand.push(z)})}if(k===2)p.field.filter(z=>effectFace(z).kind==='creature').forEach(z=>z.speedUntil=state.turnNo)}log('「これはゲームであっても遊びではない」を解決。')}
 if(id==='c28'){let shown=[];for(let i=0;i<4&&p.deck.length;i++)shown.push(p.deck.pop());let hand=shown.filter(z=>card(z.id)?.deckZone!=='extra'),bottom=shown.filter(z=>card(z.id)?.deckZone==='extra');p.hand.push(...hand);p.deck.unshift(...bottom);log(`SAOマップで${hand.length}枚を手札に加えた。`)}render()}
async function effectPlay(owner,x,sourceIndex){let p=state.players[owner],c=effectFace(x);if(sourceIndex<0&&c.kind==='weapon'){notify('ウエポン面は対応クリーチャー登場時に自動装備されます');return}let cost=c.cost,available=p.mana.filter(z=>!z.tapped).length;if(x.id==='c6'&&available>=c.cost-4){let reduced=await effectAsk('A.I.L.4：コストを4減らし、ターン終了時にマナへ置きますか？',[{label:'軽減する',value:true},{label:'通常コストで召喚',value:false}]);if(reduced){cost=Math.max(0,c.cost-4);x.ail=true}}if(available<cost){notify(`使用コスト${cost}に対し、使えるマナは${available}枚です`);return}p.mana.filter(z=>!z.tapped).slice(0,cost).forEach(z=>z.tapped=true);if(sourceIndex>=0)p.hand.splice(sourceIndex,1);else p.extra.splice(p.extra.findIndex(z=>z.uid===x.uid),1);if(c.kind==='creature'){x.tapped=false;x.summoned=true;x.enteredTurn=state.turnNo;p.field.push(x)}else if(c.kind==='spell')p.grave.push(x);else p.field.push(x);log(`${p.name}は${c.name}を${c.kind==='creature'?'召喚':c.kind==='spell'?'唱えた':'実行'}。`);render();if(c.kind==='spell')await effectSpell(owner,x);else await effectEntry(owner,x);render();if(c.kind!=='spell')showCard(c)}
function effectKeywords(x,owner){let c=effectFace(x),k=[...(c.keywords||[])],p=state.players[owner];if(c.text.join(' ').includes('スピードアタッカー'))k.push('スピード・アタッカー');if(x.speedUntil===state.turnNo)k.push('スピード・アタッカー');if(x.tempBlockerUntil===state.turnNo)k.push('ブロッカー');if(x.id==='c0')k.push('アンブロッカブル');if(x.id==='c1'&&p.field.some(z=>effectFace(z).name.includes('キリト')))k.push('T・ブレイカー');for(let w of p.field.filter(z=>z.attachedTo===x.uid)){let text=effectFace(w).text.join(' ');if(text.includes('スピードアタッカー'))k.push('スピード・アタッカー');if(text.includes('ブロッカーを与える'))k.push('ブロッカー');if(text.includes('マッハファイター'))k.push('マッハファイター');if(text.includes('T・ブレイカー'))k.push('T・ブレイカー');if(text.includes('ブロックもされない')||text.includes('ブロックされない'))k.push('アンブロッカブル')}return [...new Set(k)]}
function effectPower(x,owner){let power=effectFace(x).power||0,field=state.players[owner].field,attacking=!!(attack&&attack.owner===owner&&attack.uid===x.uid);if(x.id==='c0'&&field.some(z=>z.uid!==x.uid&&effectFace(z).name.includes('アスナ')))power+=10000;if(x.id==='c1'&&field.some(z=>effectFace(z).name.includes('キリト')))power+=10000;for(let w of field.filter(z=>z.attachedTo===x.uid)){let text=effectFace(w).text.join(' ');if(text.includes('パワーを+6000'))power+=6000;if(attacking&&text.includes('パワーアタッカー+6000'))power+=6000}return power}


function effectSaoCount(zone){return zone.filter(x=>!card(x.id)?.deckZone).length}
function effectIsSao(x){return !card(x.id)?.deckZone}
async function effectFreeCard(owner,x){let p=state.players[owner],c=effectFace(x);if(c.kind==='creature'){x.summoned=true;x.enteredTurn=state.turnNo;x.tapped=false;p.field.push(x);await effectEntry(owner,x)}else if(c.kind==='spell'){p.grave.push(x);await effectSpell(owner,x)}else{p.field.push(x);await effectEntry(owner,x)}}
