async function effectPlay(owner,x,sourceIndex,free=false){let p=state.players[owner],c=effectFace(x),opp=state.players[1-owner];if(sourceIndex<0&&c.kind==='weapon')return;if(opp.field.some(z=>z.id==='c13'&&z.face===1)&&c.cost>opp.mana.length){if(sourceIndex>=0)p.hand.splice(sourceIndex,1);else if(!free)p.extra.splice(p.extra.findIndex(z=>z.uid===x.uid),1);p.deck.unshift(x);log('狙撃手の電影の置換効果でカードを山札の下に置いた。');render();return}let candidates=[];if(c.kind==='creature'&&['c4','c5','c10'].includes(x.id)){candidates=p.field.filter(z=>effectFace(z).kind==='creature'&&effectIsSao(z)&&(x.id!=='c10'||effectFace(z).civilizations.includes('光')));if(x.id==='c10'&&!candidates.length){notify('ヒースクリフは光のSAOクリーチャーの上に進化させてください');return}}
 let cost=c.cost,available=p.mana.filter(z=>!z.tapped);if(!free&&x.id==='c0'){let n=effectSaoCount(p.field)+effectSaoCount(p.mana)+effectSaoCount(p.grave);if(n>=15){let yes=await effectAsk('G・ゼロ：コストを支払わず召喚しますか？',[{label:'G・ゼロで召喚',value:true},{label:'通常コストで召喚',value:false}]);if(yes)cost=0}}if(!free&&(x.id==='c6'||x.id==='c4')&&available.length>=c.cost-4){let yes=await effectAsk('A.I.L.4：4コスト軽減し、ターン終了時にマナへ置きますか？',[{label:'軽減する',value:true},{label:'通常コストで召喚',value:false}]);if(yes){cost=Math.max(0,cost-4);x.ail=true}}if(!free&&available.length<cost){notify(`コスト${cost}に対して使用可能なマナが足りません`);return}if(!free&&cost>0){let col=available.findIndex(z=>effectFace(z).civilizations.some(v=>c.civilizations.includes(v)));if(col<0){notify('文明が合うマナが1枚必要です');return}available.splice(col,1)[0].tapped=true;available.slice(0,cost-1).forEach(z=>z.tapped=true)}let base=null;if(candidates.length){let opts=candidates.map(z=>({label:`進化元：${effectFace(z).name}`,value:z}));if(x.id!=='c10')opts.push({label:'通常召喚する',value:null});base=await effectAsk(x.id==='c10'?'進化元を選ぶ':'進化しますか？',opts)}if(sourceIndex>=0)p.hand.splice(sourceIndex,1);else if(!free)p.extra.splice(p.extra.findIndex(z=>z.uid===x.uid),1);if(base){p.field=p.field.filter(z=>z.uid!==base.uid);p.field.filter(z=>z.attachedTo===base.uid).forEach(z=>z.attachedTo=x.uid);x.under=base}if(c.kind==='creature'){x.summoned=true;x.enteredTurn=state.turnNo;x.tapped=false;if(opp.field.some(z=>z.id==='c17'&&z.face===1))x.noAttackUntil=state.turnNo;p.field.push(x)}else if(c.kind==='spell')p.grave.push(x);else p.field.push(x);log(`${p.name}は${c.name}を${c.kind==='creature'?'召喚':c.kind==='spell'?'唱えた':'実行'}。`);if(opp.field.some(z=>z.id==='c11'&&z.face===1)&&c.cost>opp.mana.length)effectTopMana(1-owner,1);render();if(c.kind==='spell')await effectSpell(owner,x);else await effectEntry(owner,x);render();if(c.kind!=='spell')showCard(c);effectAutoProgress()}
async function action(type,owner,uid,face){let p=state.players[owner],i=p.hand.findIndex(z=>z.uid===uid),ei=p.extra.findIndex(z=>z.uid===uid),x=i>=0?p.hand[i]:ei>=0?p.extra[ei]:p.field.find(z=>z.uid===uid);if(!x)return;if(type==='playface'){x.face=+face;type='play'}let c=effectFace(x);if(type==='inspect'){showCard(c);return}if(owner!==state.turn)return;if(type==='charge'){if(i<0||state.step!==2||p.charged){notify('マナチャージステップに手札から1枚だけ置けます');return}p.charged=true;p.hand.splice(i,1);x.placedTurn=state.turnNo;effectAddMana(owner,x);log(`${p.name}は${c.name}をマナに置いた。`);render();effectAutoProgress();return}if(type==='play'){if(state.step!==3){notify('カードはメインステップに使えます');return}await effectPlay(owner,x,i>=0?i:-1);selected=null;render();effectAutoProgress();return}if(type==='attack'){if(state.step!==4){notify('攻撃ステップではありません');return}let k=effectKeywords(x,owner),mach=k.includes('マッハファイター');if(x.tapped||x.stunnedAt===state.turnNo||x.noAttackUntil===state.turnNo||x.summoned&&!k.includes('スピード・アタッカー')&&!mach){notify('このクリーチャーは今攻撃できません');return}let targetUid=null;if(mach&&x.summoned){let a=state.players[1-owner].field.filter(z=>z.tapped&&effectFace(z).kind==='creature');if(a.length)targetUid=await effectAsk('マッハファイター：攻撃先を選ぶ（選ばずプレイヤーへ攻撃できます）',[...a.map(z=>({label:effectFace(z).name,value:z.uid})),{label:'プレイヤーへ攻撃',value:null}])}x.tapped=true;attack={owner,uid,targetUid,blocked:false};selected=null;log(`${p.name}の${c.name}が攻撃。`);render();await effectShowBlock()}}
async function effectCastTriggers(){for(let owner of [attack.owner,1-attack.owner]){let p=state.players[owner],n=effectSaoCount(p.mana);for(let x of [...p.hand]){let text=effectFace(x).text.join(' '),need=text.includes('F.L.A.6')?6:text.includes('F.L.A.4')?4:0;if(!need||n<need)continue;let yes=await effectAsk(`${effectFace(x).name}のF.L.A.を使いますか？`,[{label:'コストなしで使う',value:true},{label:'使わない',value:false}]);if(yes)await effectFreeFromHand(owner,x)}}}
async function effectRevolutionZero(owner){let p=state.players[owner],x=p.hand.find(z=>z.id==='c10');if(!x||p.shields.length||!p.deck.length)return;let yes=await effectAsk('革命0トリガー：ヒースクリフを使いますか？',[{label:'山札の上を確認する',value:true},{label:'使わない',value:false}]);if(!yes)return;let base=p.deck.pop(),c=effectFace(base);if(!c.civilizations.some(v=>['光','水','自然'].includes(v))||!effectIsSao(base)){p.deck.push(base);return}p.hand=p.hand.filter(z=>z.uid!==x.uid);x.under=base;x.summoned=true;x.enteredTurn=state.turnNo;p.field.push(x);log('革命0トリガーでヒースクリフを召喚。');await effectEntry(owner,x)}
async function effectShowBlock(){await effectCastTriggers();await effectWeaponAttack();let a=state.players[attack.owner].field.find(z=>z.uid===attack.uid);if(!a){attack=null;render();effectAutoEndAttack();return}await effectSmashBurst(attack.owner,a);a=state.players[attack.owner].field.find(z=>z.uid===attack.uid);if(!a){attack=null;render();effectAutoEndAttack();return}if(attack.targetUid){let d=state.players[1-attack.owner].field.find(z=>z.uid===attack.targetUid);if(d)await effectBattle(attack.owner,a,1-attack.owner,d);await effectAttackEnd(state.players[attack.owner].field.find(z=>z.uid===a.uid));attack=null;render();effectAutoEndAttack();return}await effectRevolutionZero(1-attack.owner);a=state.players[attack.owner].field.find(z=>z.uid===attack.uid);if(!a){attack=null;render();effectAutoEndAttack();return}let di=1-attack.owner,d=state.players[di],blockers=d.field.filter(z=>effectKeywords(z,di).includes('ブロッカー')&&!z.tapped&&z.stunnedAt!==state.turnNo);if(!blockers.length||effectKeywords(a,attack.owner).includes('アンブロッカブル')){await effectResolveAttack();return}let uid=await effectAsk('ブロックしますか？',[...blockers.map(z=>({label:`${effectFace(z).name}でブロック`,value:z.uid})),{label:'ブロックしない',value:null}]);if(!uid){await effectResolveAttack();return}let b=blockers.find(z=>z.uid===uid);b.tapped=true;attack.blocked=true;await effectBattle(attack.owner,a,di,b);await effectAttackEnd(state.players[attack.owner].field.find(z=>z.uid===a.uid));attack=null;render();effectAutoEndAttack()}
async function effectBattle(ai,a,di,d){let ac=effectFace(a),dc=effectFace(d),ap=effectPower(a,ai),dp=effectPower(d,di),aw=ap>dp,dw=dp>ap,tie=ap===dp,asl=ac.text.join(' ').includes('スレイヤー'),dsl=dc.text.join(' ').includes('スレイヤー');if(aw||tie||dsl){state.players[ai].field=state.players[ai].field.filter(z=>z.uid!==a.uid);state.players[ai].grave.push(a)}if(dw||tie||asl){state.players[di].field=state.players[di].field.filter(z=>z.uid!==d.uid);state.players[di].grave.push(d)}if(aw&&state.players[ai].field.some(z=>z.id==='c13'&&z.face===0&&z.attachedTo===a.uid))a.tapped=false;if(dw&&state.players[di].field.some(z=>z.id==='c13'&&z.face===0&&z.attachedTo===d.uid))d.tapped=false;log(`${ac.name}と${dc.name}がバトル。`);render()}
