async function showCard(c){$('dialogContent').innerHTML=`<div class="eyebrow">${c.rarity} · ${c.civilizations.join(' / ')}</div><h3>${c.name}</h3><div class="sub">コスト ${c.cost}${c.power?' · パワー '+c.power:''}</div><div class="rule"></div><p style="line-height:1.9;font-size:13px">${c.text.map(t=>`・${t}`).join('<br>')}</p>`;$('overlay').style.display='flex'}
