function effectCanAttack(owner){let p=state.players[owner];return p.field.some(x=>{if(effectFace(x).kind!=='creature'||x.attachedTo)return false;let k=effectKeywords(x,owner);if(x.tapped||x.stunnedAt===state.turnNo||x.noAttackUntil===state.turnNo)return false;if(!x.summoned||k.includes('スピード・アタッカー'))return true;if(k.includes('マッハファイター'))return true;return false})}
